INSERT INTO feature VALUES('unit-surface-tier','workflow','A surface feature states its tier',NULL,'implemented','ordinary',NULL,'A `kind:feature` unit in `area:surface` or `area:theory` carries `## Surface`: `tier <0–4> — <why the tier below does not read well enough>` on the owner''s scale, names and combinators, a user notation, a reader, an attribute or a clause position, or `none — <why>`. `unit:check`, `issue:file`, the issues workflow and `claim:next` refuse a unit without it, and an issue the coordinator signed is never judged for it again.',NULL,'.config/bodies/unit.json .config/claims/next.json .config/bodies/signed.json .config/issues/form.json',NULL,NULL);
